
import type { MoneyValue } from './MoneyValue.js';
import type { SelectableOrderPaymentIntent } from './SelectableOrderPaymentIntent.js';

export type PaymentCollectionStripe = { "account_id"?: string; /** Stripe Elements collection guidance. Follow next_step in the browser, then submit the result to submit_to through Flint. */ "elements"?: { "amount_money"?: MoneyValue; "digital_wallets"?: Array<string>; /** Whether Elements is collecting a payment source for an immediate payment or a setup source for future use. */ "mode": "payment" | "setup" | (string & {}); /** Browser collection operation to perform before calling submit_to. */ "next_step": "collect_payment_source" | "collect_setup_payment_source" | "create_confirmation_token" | (string & {}); /** Stripe Elements payment method creation mode. Follow next_step: standalone PaymentIntents and checkout-authenticated order collection create a ConfirmationToken, while merchant-authenticated order collection and setup collection create a PaymentMethod. */ "payment_method_creation": "manual" | (string & {}); "payment_method_options"?: Record<string, string>; "payment_method_types": Array<string>; "selectable_payment_intents"?: Array<SelectableOrderPaymentIntent>; /** Flint operation that accepts the result of next_step. */ "submit_to": "pay_order" | "confirm_payment_intent" | (string & {}); }; "publishable_key"?: string; "return_url"?: string; };
